-- `ALTER TABLE … ADD GENERATED …` naming a column that is already an identity
-- column is rejected — Postgres SQLSTATE 55000 (object_not_in_prerequisite_state):
-- `column "id" of relation "t" is already an identity column`. pglet matches rather
-- than silently flipping ALWAYS↔BY DEFAULT.
-- @expect-error: the column is already an identity column
-- @setup
CREATE TABLE t (id int GENERATED ALWAYS AS IDENTITY, name text);
-- @test
ALTER TABLE t ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
